"""
    Get a given value's percent in the range.
    :param value: value
    :param minimum: the range's minimum value
    :param maximum: the range's maximum value
    :return: percent float
    """
def get_percent(value: Any, minimum: Any, maximum: Any) -> object {
    if (minimum == maximum) {
        return 100;
    }
    return max(0, min(100, (((value - minimum) * 100) / (maximum - minimum))));
}

"""
    Calculates each interval performance.
    :param label_intervals: List of time series.
    :return:
        - labels: The performance related to each element in the input, calculated as the subtraction between its
                  last and first element.
    """
def get_labels(label_intervals: Any) -> object {
    labels = [];
    for data_ in label_intervals {
        labels.append((data_[-1] - data_[0]));
    }
    return labels;
}
